import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { getSupabase, isSupabaseConfigured } from "@/services/supabase-client";
import { useAuth } from "./auth-context";
import type { Order, CartItem } from "@/types/payplate";
import { useWallet } from "./wallet-context";

type OrdersState = {
  orders: Order[];
  isLoading: boolean;
  createOrder: (params: {
    items: CartItem[]; subtotalCents: number; studentDiscountCents: number;
    promoDiscountCents: number; deliveryFeeCents: number; totalCents: number;
    orderType: "delivery" | "pickup"; paymentMethod: "wallet" | "card";
    restaurantId: string; restaurantName: string;
  }) => Order;
  getOrderById: (id: string) => Order | undefined;
  recentOrders: Order[];
};

const OrdersContext = createContext<OrdersState | undefined>(undefined);

export function OrdersProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const wallet = useWallet();

  useEffect(() => {
    if (!user || !isSupabaseConfigured) { setIsLoading(false); return; }
    const sb = getSupabase();
    if (!sb) { setIsLoading(false); return; }
    setIsLoading(true);
    async function loadOrders() {
      const { data: dbOrders } = await sb!.from("orders").select("*, order_items(*)").eq("user_id", user!.id).order("created_at", { ascending: false });
      if (dbOrders && dbOrders.length > 0) {
        const mapped: Order[] = dbOrders.map((o: Record<string, unknown>) => ({
          id: o.id as string,
          items: ((o.order_items as Record<string, unknown>[]) ?? []).map((oi) => ({
            item: { id: oi.menu_item_id as string, restaurantId: o.restaurant_id as string, name: oi.name as string, description: "", priceCents: oi.price_cents as number, image: (oi.image as string) ?? "", prepTimeMinutes: 0, dietaryTags: [], category: "" },
            quantity: oi.quantity as number,
          })),
          subtotalCents: o.subtotal_cents as number, studentDiscountCents: o.student_discount_cents as number,
          promoDiscountCents: o.promo_discount_cents as number, deliveryFeeCents: o.delivery_fee_cents as number,
          totalCents: o.total_cents as number, status: o.status as Order["status"],
          orderType: o.order_type as Order["orderType"], paymentMethod: o.payment_method as Order["paymentMethod"],
          restaurantId: o.restaurant_id as string, restaurantName: o.restaurant_name as string,
          createdAt: o.created_at as string, estimatedReadyAt: o.estimated_ready_at as string,
        }));
        setOrders(mapped);
      }
      setIsLoading(false);
    }
    loadOrders();
  }, [user]);

  const value = useMemo<OrdersState>(() => ({
    orders, isLoading,
    createOrder(params) {
      const now = new Date();
      const estimatedReady = new Date(now.getTime() + 25 * 60000);
      const order: Order = { id: `order-${Date.now()}`, ...params, status: "preparing", createdAt: now.toISOString(), estimatedReadyAt: estimatedReady.toISOString() };
      setOrders((prev) => [order, ...prev]);
      if (user && isSupabaseConfigured) {
        const sb = getSupabase();
        if (sb) {
          const orderId = crypto.randomUUID();
          sb.from("orders").insert({ id: orderId, user_id: user.id, restaurant_name: params.restaurantName, status: "preparing", order_type: params.orderType, payment_method: params.paymentMethod, subtotal_cents: params.subtotalCents, student_discount_cents: params.studentDiscountCents, promo_discount_cents: params.promoDiscountCents, delivery_fee_cents: params.deliveryFeeCents, total_cents: params.totalCents, estimated_ready_at: estimatedReady.toISOString() }).then(({ data, error }) => {
            if (!error && data) {
              const items = params.items.map((ci) => ({ order_id: orderId, menu_item_id: ci.item.id, name: ci.item.name, quantity: ci.quantity, price_cents: ci.item.priceCents, image: ci.item.image }));
              sb.from("order_items").insert(items).then(() => { setOrders((prev) => prev.map((o) => o.id === order.id ? { ...o, id: orderId } : o)); });
            }
          });
        }
      }
      wallet.deduct(params.totalCents, `${params.restaurantName} — Order`, params.restaurantName);
      return order;
    },
    getOrderById(id) { return orders.find((o) => o.id === id); },
    get recentOrders() { return orders.slice(0, 5); },
  }), [orders, isLoading, wallet, user]);

  return <OrdersContext.Provider value={value}>{children}</OrdersContext.Provider>;
}

export function useOrders() {
  const ctx = useContext(OrdersContext);
  if (!ctx) throw new Error("useOrders must be used within OrdersProvider");
  return ctx;
}

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { getSupabase, isSupabaseConfigured } from "@/services/supabase-client";
import { useAuth } from "./auth-context";
import { mockTransactions } from "@/services/payplate-data";
import type { Transaction, RewardTier } from "@/types/payplate";

type WalletState = {
  balanceCents: number; transactions: Transaction[]; totalSpentThisMonthCents: number;
  rewardPoints: number; tier: RewardTier; tierProgressPercent: number; isLoading: boolean;
  topUp: (amountCents: number) => void;
  deduct: (amountCents: number, description: string, merchantName?: string) => void;
  addReward: (amountCents: number, description: string) => void;
  refresh: () => void;
};

const WalletContext = createContext<WalletState | undefined>(undefined);
const MOCK_INITIAL_BALANCE = 74500;
const MOCK_INITIAL_POINTS = 360;

function tierFromPoints(points: number): { tier: RewardTier; progress: number } {
  if (points >= 2000) return { tier: "diamond", progress: 100 };
  if (points >= 800) return { tier: "gold", progress: ((points - 800) / 1200) * 100 };
  if (points >= 500) return { tier: "silver", progress: ((points - 500) / 300) * 100 };
  return { tier: "bronze", progress: (points / 500) * 100 };
}

export function WalletProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [balanceCents, setBalanceCents] = useState(MOCK_INITIAL_BALANCE);
  const [transactions, setTransactions] = useState<Transaction[]>(mockTransactions);
  const [rewardPoints, setRewardPoints] = useState(MOCK_INITIAL_POINTS);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (!user || !isSupabaseConfigured) { setIsLoading(false); return; }
    const sb = getSupabase();
    if (!sb) { setIsLoading(false); return; }
    async function loadWallet() {
      const { data: profile } = await sb!.from("profiles").select("wallet_balance_cents, reward_points, reward_tier").eq("id", user!.id).maybeSingle();
      if (profile) { setBalanceCents(profile.wallet_balance_cents ?? 0); setRewardPoints(profile.reward_points ?? 0); }
      const { data: txns } = await sb!.from("transactions").select("*").eq("user_id", user!.id).order("created_at", { ascending: false }).limit(50);
      if (txns && txns.length > 0) {
        setTransactions(txns.map((t: Record<string, unknown>) => ({ id: t.id as string, type: t.type as Transaction["type"], amountCents: t.amount_cents as number, description: t.description as string, merchantName: t.merchant_name as string | undefined, date: t.created_at as string })));
      }
      setIsLoading(false);
    }
    loadWallet();
  }, [user]);

  const { tier, progress: tierProgressPercent } = tierFromPoints(rewardPoints);
  const totalSpentThisMonthCents = useMemo(() => transactions.filter((t) => t.type === "payment").reduce((s, t) => s + Math.abs(t.amountCents), 0), [transactions]);

  async function persistTransaction(txn: Omit<Transaction, "id" | "date">) {
    if (!user || !isSupabaseConfigured) return;
    const sb = getSupabase();
    if (!sb) return;
    await sb.from("transactions").insert({ user_id: user.id, type: txn.type, amount_cents: txn.amountCents, description: txn.description, merchant_name: txn.merchantName ?? null });
  }

  async function updateProfileBalance(newBalance: number, pointsDelta: number = 0) {
    if (!user || !isSupabaseConfigured) return;
    const sb = getSupabase();
    if (!sb) return;
    await sb.from("profiles").update({ wallet_balance_cents: newBalance, reward_points: rewardPoints + pointsDelta }).eq("id", user.id);
  }

  const value = useMemo<WalletState>(() => ({
    balanceCents, transactions, totalSpentThisMonthCents, rewardPoints, tier, tierProgressPercent, isLoading,
    topUp(amountCents) {
      const newBalance = balanceCents + amountCents;
      setBalanceCents(newBalance);
      const txn: Transaction = { id: `t-${Date.now()}`, type: "topup", amountCents, description: "Wallet top-up", date: new Date().toISOString() };
      setTransactions((prev) => [txn, ...prev]);
      persistTransaction(txn); updateProfileBalance(newBalance);
    },
    deduct(amountCents, description, merchantName) {
      const newBalance = balanceCents - amountCents;
      setBalanceCents(newBalance);
      const pointsEarned = Math.floor(amountCents / 100);
      setRewardPoints((prev) => prev + pointsEarned);
      const txn: Transaction = { id: `t-${Date.now()}`, type: "payment", amountCents: -amountCents, description, merchantName, date: new Date().toISOString() };
      setTransactions((prev) => [txn, ...prev]);
      persistTransaction(txn); updateProfileBalance(newBalance, pointsEarned);
    },
    addReward(amountCents, description) {
      const txn: Transaction = { id: `t-${Date.now()}`, type: "reward", amountCents, description, date: new Date().toISOString() };
      setTransactions((prev) => [txn, ...prev]);
      persistTransaction(txn);
    },
    refresh() {
      setIsLoading(true);
      if (user && isSupabaseConfigured) {
        const sb = getSupabase();
        if (sb) {
          sb.from("transactions").select("*").eq("user_id", user.id).order("created_at", { ascending: false }).limit(50).then(({ data: txns }) => {
            if (txns) { setTransactions(txns.map((t: Record<string, unknown>) => ({ id: t.id as string, type: t.type as Transaction["type"], amountCents: t.amount_cents as number, description: t.description as string, merchantName: t.merchant_name as string | undefined, date: t.created_at as string }))); }
            setIsLoading(false);
          });
          return;
        }
      }
      setIsLoading(false);
    },
  }), [balanceCents, transactions, totalSpentThisMonthCents, rewardPoints, tier, tierProgressPercent, isLoading, user]);

  return <WalletContext.Provider value={value}>{children}</WalletContext.Provider>;
}

export function useWallet() {
  const ctx = useContext(WalletContext);
  if (!ctx) throw new Error("useWallet must be used within WalletProvider");
  return ctx;
}

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { rewardService } from "@/services/payplate-api";
import type { Reward, Challenge } from "@/types/payplate";

type RewardsState = {
  rewards: Reward[];
  challenges: Challenge[];
  isLoading: boolean;
  redeem: (rewardId: string) => boolean;
};

const RewardsContext = createContext<RewardsState | undefined>(undefined);

export function RewardsProvider({ children }: { children: ReactNode }) {
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [challenges, setChallenges] = useState<Challenge[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    let active = true;
    Promise.all([rewardService.getAll(), rewardService.getChallenges()]).then(([r, c]) => {
      if (active) { setRewards(r); setChallenges(c); setIsLoading(false); }
    });
    return () => { active = false; };
  }, []);

  const value = useMemo<RewardsState>(
    () => ({
      rewards, challenges, isLoading,
      redeem(rewardId) {
        setRewards((prev) => prev.map((r) => (r.id === rewardId ? { ...r, isEarned: true } : r)));
        return true;
      },
    }),
    [rewards, challenges, isLoading],
  );

  return <RewardsContext.Provider value={value}>{children}</RewardsContext.Provider>;
}

export function useRewards() {
  const ctx = useContext(RewardsContext);
  if (!ctx) throw new Error("useRewards must be used within RewardsProvider");
  return ctx;
}

import { createContext, useContext, useMemo, useState, type ReactNode } from "react";

type Settings = {
  notifications: { orderUpdates: boolean; rewards: boolean; offers: boolean; };
  privacy: { showProfile: boolean; shareOrderHistory: boolean; };
  payment: { defaultMethod: "wallet" | "card"; autoTopUp: boolean; };
};

type SettingsState = {
  settings: Settings;
  updateNotification: (key: keyof Settings["notifications"], value: boolean) => void;
  updatePrivacy: (key: keyof Settings["privacy"], value: boolean) => void;
  updatePayment: (key: keyof Settings["payment"], value: boolean | string) => void;
};

const defaultSettings: Settings = {
  notifications: { orderUpdates: true, rewards: true, offers: false },
  privacy: { showProfile: true, shareOrderHistory: false },
  payment: { defaultMethod: "wallet", autoTopUp: false },
};

const SettingsContext = createContext<SettingsState | undefined>(undefined);

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<Settings>(() => {
    try { const raw = localStorage.getItem("payplate_settings"); if (raw) return { ...defaultSettings, ...JSON.parse(raw) }; } catch { /* ignore */ }
    return defaultSettings;
  });
  function persist(next: Settings) { setSettings(next); localStorage.setItem("payplate_settings", JSON.stringify(next)); }
  const value = useMemo<SettingsState>(() => ({
    settings,
    updateNotification(key, val) { persist({ ...settings, notifications: { ...settings.notifications, [key]: val } }); },
    updatePrivacy(key, val) { persist({ ...settings, privacy: { ...settings.privacy, [key]: val } }); },
    updatePayment(key, val) { persist({ ...settings, payment: { ...settings.payment, [key]: val } }); },
  }), [settings]);
  return <SettingsContext.Provider value={value}>{children}</SettingsContext.Provider>;
}

export function useSettings() {
  const ctx = useContext(SettingsContext);
  if (!ctx) throw new Error("useSettings must be used within SettingsProvider");
  return ctx;
}

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { restaurantService } from "@/services/payplate-api";
import type { Restaurant } from "@/types/payplate";

type RestaurantsState = {
  restaurants: Restaurant[];
  isLoading: boolean;
  error: string | null;
  search: (query: string) => Promise<Restaurant[]>;
  getById: (id: string) => Promise<Restaurant | null>;
  filterByCategory: (category: string) => Promise<Restaurant[]>;
  retry: () => void;
};

const RestaurantsContext = createContext<RestaurantsState | undefined>(undefined);

export function RestaurantsProvider({ children }: { children: ReactNode }) {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  function load() {
    setIsLoading(true);
    setError(null);
    restaurantService.getAll().then((data) => {
      setRestaurants(data);
      setIsLoading(false);
    }).catch(() => {
      setError("Failed to load restaurants. Please try again.");
      setIsLoading(false);
    });
  }

  useEffect(() => { load(); }, []);

  const value = useMemo<RestaurantsState>(
    () => ({
      restaurants,
      isLoading,
      error,
      async search(query) { return restaurantService.search(query); },
      async getById(id) { return restaurantService.getById(id); },
      async filterByCategory(category) { return restaurantService.getByCategory(category); },
      retry() { load(); },
    }),
    [restaurants, isLoading, error],
  );

  return <RestaurantsContext.Provider value={value}>{children}</RestaurantsContext.Provider>;
}

export function useRestaurants() {
  const ctx = useContext(RestaurantsContext);
  if (!ctx) throw new Error("useRestaurants must be used within RestaurantsProvider");
  return ctx;
}

import { useEffect, useState } from "react";

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    function onChange() { setReduced(mq.matches); }
    mq.addEventListener?.("change", onChange);
    return () => mq.removeEventListener?.("change", onChange);
  }, []);

  return reduced;
}

